-- Migration 012: Demo seed data + schema amendments
-- ============================================================
-- SCHEMA AMENDMENTS
-- 1. Fix device_type values for catalogue templates
-- 2. Add profile defaults to user_profile
-- 3. Add is_demo flag to measurements + calculated_marker_values
-- ============================================================

-- 1. Fix device_type values (was: blood_analyzer / bp_monitor / scale)
UPDATE devices SET device_type = 'fora6'       WHERE device_name = 'Fora 6 Connect' AND user_id IS NULL;
UPDATE devices SET device_type = 'qardio_arm'  WHERE device_name = 'Qardio Arm'     AND user_id IS NULL;
UPDATE devices SET device_type = 'qardio_base' WHERE device_name = 'Qardiobase 2'   AND user_id IS NULL;

-- 2. Profile defaults
ALTER TABLE user_profile
    ADD COLUMN IF NOT EXISTS default_waist_cm  NUMERIC(5,1),
    ADD COLUMN IF NOT EXISTS default_weight_kg NUMERIC(5,1);

-- 3. Demo flags
ALTER TABLE measurements
    ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT false;

ALTER TABLE calculated_marker_values
    ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT false;

-- Index for fast demo filtering
CREATE INDEX IF NOT EXISTS idx_measurements_is_demo ON measurements(user_id) WHERE is_demo = true;

